# Question bank, sections 1-3. Types: mc (pick one), tf (true/false), out (what does it print?), blank (type the missing code).
# a = index of the right choice (mc/tf/out) or a list of accepted answers (blank). lvl 1 easy, 2 medium, 3 hard.
Q = []
def mc(s, p, lvl, q, choices, a, why, code=None): Q.append(dict(s=s, p=p, t="mc", lvl=lvl, q=q, code=code, choices=choices, a=a, why=why))
def tf(s, p, lvl, q, a, why, code=None): Q.append(dict(s=s, p=p, t="tf", lvl=lvl, q=q, code=code, choices=["True", "False"], a=0 if a else 1, why=why))
def out(s, p, lvl, code, choices, a, why, q="What does this print?"): Q.append(dict(s=s, p=p, t="out", lvl=lvl, q=q, code=code, choices=choices, a=a, why=why))
def blank(s, p, lvl, q, code, answers, why): Q.append(dict(s=s, p=p, t="blank", lvl=lvl, q=q, code=code, a=answers, why=why))

# ---------------- Section 1: Core Fundamentals ----------------
S = 1
mc(S, "1.1", 1, "Which type should hold money amounts?", ["double", "float", "decimal", "int"], 2, "decimal stores base-10 digits exactly, so 0.1 + 0.2 is exactly 0.3. double works in base 2 and rounds.")
out(S, "1.1", 2, "Console.WriteLine(0.1 + 0.2 == 0.3);", ["True", "False", "Compile error", "Exception"], 1, "0.1 and 0.2 can't be stored exactly as double, so their sum is 0.30000000000000004.")
out(S, "1.1", 2, "Console.WriteLine(0.1m + 0.2m == 0.3m);", ["True", "False", "Compile error", "Exception"], 0, "The m suffix makes decimal literals; decimal adds them exactly.")
out(S, "1.1", 2, "int big = int.MaxValue;\nConsole.WriteLine(unchecked(big + 1));", ["2147483648", "-2147483648", "OverflowException", "0"], 1, "unchecked lets the int wrap around to int.MinValue silently. It is also the default when you write neither keyword.")
mc(S, "1.1", 2, "What does checked(int.MaxValue + someOne) do at run time when it overflows?", ["Wraps to int.MinValue", "Returns int.MaxValue", "Throws OverflowException", "Returns 0"], 2, "checked turns a silent wrap-around into a loud OverflowException.")
blank(S, "1.1", 1, "Fill in the suffix that makes this a decimal literal.", "decimal price = 19.99____;", ["m", "M"], "m (or M) marks a decimal literal. Without it, 19.99 is a double and won't convert implicitly.")
mc(S, "1.1", 2, "Which method reads a number from text without throwing on bad input?", ["int.Parse", "Convert.ToInt32", "int.TryParse", "(int)text"], 2, "TryParse returns false for bad input and gives the number through an out parameter.")
blank(S, "1.1", 2, "Complete the safe parse.", "if (int.____(text, out int number))\n{\n    Console.WriteLine(number);\n}", ["TryParse"], "int.TryParse(text, out int number) returns true only when the text is a valid int.")
tf(S, "1.1", 1, "DateOnly stores a calendar date without a time of day.", True, "DateOnly (and TimeOnly for times) avoid the hidden midnight that DateTime always carries.")
mc(S, "1.1", 2, "The ?? operator...", ["compares two values", "gives the right side when the left side is null", "throws when the left is null", "converts null to 0"], 1, "a ?? b means: a, unless a is null, then b.")
out(S, "1.1", 2, "string? name = null;\nConsole.WriteLine(name?.Length ?? -1);", ["0", "-1", "null", "NullReferenceException"], 1, "?. stops at null and gives null; ?? then supplies -1.")
blank(S, "1.1", 2, "Assign only if the variable is still null.", "settings ____ LoadSettings();", ["??="], "??= assigns the right side only when the left side is null.")
mc(S, "1.2", 1, "Which is a switch EXPRESSION?", ["switch (x) { case 1: return \"a\"; }", "x switch { 1 => \"a\", _ => \"b\" }", "if (x is 1) { }", "case x when x > 1:"], 1, "A switch expression uses => arms and produces a value.")
out(S, "1.2", 2, "int score = 720;\nstring band = score switch\n{\n    >= 800 => \"Excellent\",\n    >= 700 => \"Good\",\n    _ => \"Fair\",\n};\nConsole.WriteLine(band);", ["Excellent", "Good", "Fair", "Compile error"], 1, "Relational patterns are checked top to bottom; 720 fails >= 800 and matches >= 700.")
blank(S, "1.2", 1, "Fill in the 'anything else' arm.", "string label = code switch\n{\n    1 => \"one\",\n    ____ => \"other\",\n};", ["_"], "The discard pattern _ matches any value, like default in a switch statement.")
mc(S, "1.2", 2, "What does 'and' do in: score is >= 600 and < 700", ["Bitwise AND", "Combines two patterns: both must match", "Logical AND of two bools", "Nothing, it's a comment"], 1, "and, or, not combine patterns.")
tf(S, "1.2", 2, "A switch expression that doesn't cover every possible value gives a compiler warning.", True, "Warning CS8509: the switch expression is not exhaustive.")
mc(S, "1.2", 3, "GetType() == typeof(CardPayment) vs payment is CardPayment: what's the difference?", ["None", "'is' also matches classes derived from CardPayment", "GetType() also matches derived classes", "'is' only works with interfaces"], 1, "GetType() == typeof(...) needs the exact type; 'is' accepts subclasses too.")
blank(S, "1.2", 2, "Match a list starting with \"deposit\" and capture the second item.", "if (words is [\"deposit\", ____ amount])\n{\n}", ["var"], "List patterns: [\"deposit\", var amount] matches two items and captures the second.")
mc(S, "1.2", 2, "Which pattern checks a property?", ["parcel is { Weight: > 20 }", "parcel is > 20", "parcel is Weight(20)", "parcel == { Weight: 20 }"], 0, "A property pattern lists properties in { } with their own patterns.")
mc(S, "1.3", 1, "How do you return two values without writing a class?", ["Two return statements", "A tuple like (decimal Total, int Count)", "A params array", "You can't"], 1, "A named tuple returns several values at once.")
blank(S, "1.3", 1, "Swap two variables without a temporary one.", "(left, right) = (____, ____);", ["right, left", "right,left"], "(left, right) = (right, left) builds a tuple of the old values and deconstructs it.")
out(S, "1.3", 2, "(int Width, int Height) a = (3, 4);\n(int Count, int Total) b = (3, 4);\nConsole.WriteLine(a == b);", ["True", "False", "Compile error", "Exception"], 0, "Tuple == compares element by element by position; the names don't matter.")
mc(S, "1.3", 3, "JsonSerializer.Serialize(item) where item is (string Name, int Quantity) gives...", ["{\"Name\":...,\"Quantity\":...}", "{}", "[\"Tea\",12]", "An exception"], 1, "Tuple elements are fields, and System.Text.Json skips fields by default. Even with IncludeFields you get Item1/Item2: names exist only in source code.")
blank(S, "1.3", 2, "Ignore the third value when deconstructing.", "var (total, count, ____) = Summarize(prices);", ["_"], "The discard _ throws away a value you don't need.")
mc(S, "1.3", 2, "What makes a normal class usable in var (a, b) = obj;?", ["Implementing IDeconstructable", "A Deconstruct method with out parameters", "Making it a struct", "Overriding ToString"], 1, "Any type with a Deconstruct(out ..., out ...) method can be deconstructed; records get one for free.")
tf(S, "1.3", 2, "Value tuples are mutable structs: you can change copy.X without changing the original.", True, "ValueTuple has public fields and is copied by value.")
blank(S, "1.4", 1, "Make a copy of p1 with a new name.", "var p2 = p1 ____ { Name = \"Filip Ekberg\" };", ["with"], "A with expression copies the record and changes only the listed properties.")
out(S, "1.4", 2, "var p1 = new Person(\"Anna\", 34);\nvar p2 = p1 with { Name = \"Kim\" };\nConsole.WriteLine(p1.Name);", ["Anna", "Kim", "null", "Compile error"], 0, "with makes a NEW record; the original is unchanged.")
mc(S, "1.4", 3, "A record has a List<string> Orders. After var copy = buyer with { Name = \"Kim\" }; copy.Orders.Add(\"Tea\") ...", ["Only copy has Tea", "Both buyer and copy have Tea", "It throws", "with deep-copies the list"], 1, "with is a SHALLOW copy: both records point at the same list.")
mc(S, "1.4", 3, "Two records new Person(\"Anna\") each with their own empty List property. Are they equal?", ["Yes, records compare by value", "No, the lists are compared by reference", "Only if ToString matches", "Compile error"], 1, "Record equality compares each member; a List compares by reference, so two different lists make the records unequal.")
mc(S, "1.4", 2, "What does 'sealed' on a record do?", ["Makes it immutable", "Stops other types inheriting from it", "Hides it from other assemblies", "Makes it a struct"], 1, "Inheriting from a sealed type is compile error CS0509.")
blank(S, "1.4", 3, ".NET 10: start an extension block for TransportationModel.", "public static class TransportationExtensions\n{\n    ____(TransportationModel transport)\n    {\n        public string ToLabel() { ... }\n    }\n}", ["extension"], "extension(Type name) { } blocks can add methods, properties and static members.")
tf(S, "1.4", 3, ".NET 10 extension blocks can add extension PROPERTIES, which the old 'this' style cannot.", True, "The old style (static method with 'this' on the first parameter) only adds methods.")
mc(S, "1.4", 3, "Why does a switch over every sealed subtype of an abstract record still need _ => ...?", ["Records can't be switched", "Another project could add a new subtype, so the compiler can't know the list is complete", "sealed types aren't checked", "It doesn't need it"], 1, "Warning CS8509 without it. A future 'closed' keyword would tell the compiler the list is complete.")
tf(S, "1.4", 2, "'with' works on normal classes.", False, "Compile error CS8858. It works on records, record structs, structs and anonymous types.")
mc(S, "1.4", 3, "A record validates Name only in its constructor. What does valid with { Name = \"\" } do?", ["Throws", "Succeeds: with doesn't run the constructor's check", "Compile error", "Sets Name to null"], 1, "with copies the object and calls the init accessor, skipping constructor logic. Put the check in init.")
blank(S, "1.4", 3, ".NET 10: assign the hidden backing field inside init.", "public string Name { get; init => ____ = value; }", ["field"], "The field keyword refers to the compiler-generated backing field.")

# ---------------- Section 2: Collections & LINQ ----------------
S = 2
mc(S, "2.1", 1, "Fastest way to look up a product by its code?", ["List<Product>", "Dictionary<string, Product>", "Array", "Queue<Product>"], 1, "Dictionary lookups take about the same time however many items there are (O(1)); a List checks one by one.")
mc(S, "2.1", 1, "Which collection never holds duplicates?", ["List<T>", "Queue<T>", "HashSet<T>", "Stack<T>"], 2, "Add returns false when the item is already there.")
blank(S, "2.1", 1, "Read a dictionary value without an exception if the key is missing.", "if (stock.____(\"SKU-1\", out int quantity))\n{\n}", ["TryGetValue"], "TryGetValue returns false instead of throwing KeyNotFoundException.")
out(S, "2.1", 2, "var stock = new Dictionary<string, int>();\nConsole.WriteLine(stock[\"Tea\"]);", ["0", "null", "KeyNotFoundException", "Compile error"], 2, "The indexer throws for a missing key. Use TryGetValue or GetValueOrDefault.")
mc(S, "2.1", 2, "When does a LINQ Where(...) query run?", ["When you write it", "When you loop over it or call ToList/Count", "At compile time", "Never"], 1, "Deferred execution: a query is a recipe until something reads it.")
mc(S, "2.1", 2, "First() vs Single() on a sequence with TWO matches:", ["Both return the first", "First returns the first; Single throws", "Both throw", "Single returns the first"], 1, "Single insists on exactly one match.")
out(S, "2.1", 2, "var list = new List<int>();\nConsole.WriteLine(list.FirstOrDefault());", ["null", "0", "InvalidOperationException", "-1"], 1, "FirstOrDefault returns default(int), which is 0, for an empty sequence.")
mc(S, "2.1", 2, "Which is better to check 'is there at least one'?", ["Count() > 0", "Any()", "ToList().Count > 0", "First() != null"], 1, "Any() stops at the first item; Count() may walk the whole sequence.")
blank(S, "2.1", 2, "Group products by category.", "var groups = products.____(product => product.Category);", ["GroupBy"], "GroupBy returns groups, each with a Key and its items.")
blank(S, "2.1", 2, "Total value of the stock.", "decimal total = products.____(product => product.Price * product.Quantity);", ["Sum"], "Sum adds up the selector's results.")
mc(S, "2.1", 2, "new { Category = g.Key, Value = ... } creates...", ["A record", "An anonymous type", "A tuple", "A dictionary"], 1, "Anonymous types have no name you can write, so they work inside one method (with var).")
tf(S, "2.1", 1, "OrderBy changes the original list.", False, "LINQ returns a new sequence; List.Sort() sorts in place.")
mc(S, "2.1", 3, "FrozenDictionary is best when...", ["Items change often", "Built once at startup and read many times", "Keys must stay sorted", "You need thread-safe writes"], 1, "Slower to build, fastest to read, can never change (5.3's benchmark measured it).")
mc(S, "2.2", 1, "What does yield return do?", ["Ends the method", "Hands out one item and pauses until the next is asked for", "Returns a List", "Starts a thread"], 1, "The compiler turns the method into an enumerator that resumes after each yield.")
out(S, "2.2", 2, "IEnumerable<int> Numbers()\n{\n    Console.Write(\"start \");\n    yield return 1;\n}\nvar numbers = Numbers();\nConsole.Write(\"after \");", ["start after", "after", "start", "after start"], 1, "Calling an iterator runs NOTHING until someone loops over it.")
blank(S, "2.2", 1, "Stop an iterator early.", "if (string.IsNullOrWhiteSpace(line))\n{\n    yield ____;\n}", ["break"], "yield break ends the sequence.")
mc(S, "2.2", 2, "When is the error thrown in: IEnumerable<string> Gen(int n) { ThrowIfNegative(n); ... yield return ...; } called as Gen(-1)?", ["At the call", "At the first loop step", "Never", "At compile time"], 1, "Argument checks inside an iterator run late. Fix: check first, then return a local iterator function.")
mc(S, "2.2", 2, "foreach over an iterator that reads a file, then 'break' after the first line. Is the file closed?", ["No, it leaks", "Yes, foreach calls Dispose(), which runs the iterator's finally/using", "Only on garbage collection", "Only if you call Close()"], 1, "foreach always disposes the enumerator, even after break.")
blank(S, "2.2", 2, "The one method IEnumerable<T> requires.", "public IEnumerator<string> ____()\n{\n    return new ShelfEnumerator(items.ToArray());\n}", ["GetEnumerator"], "foreach calls GetEnumerator(), then MoveNext()/Current.")
mc(S, "2.2", 2, "Which two members does foreach use on an IEnumerator<T>?", ["Next() and Value", "MoveNext() and Current", "HasNext and Get()", "Read() and Item"], 1, "while (cursor.MoveNext()) { var item = cursor.Current; }")
tf(S, "2.2", 2, "Adding to a List<T> while looping it with foreach throws InvalidOperationException.", True, "\"Collection was modified; enumeration operation may not execute.\"")
mc(S, "2.2", 3, "query.Count() then query.First() on a database query runs the query...", ["once", "twice", "never", "only if cached"], 1, "Each use re-runs the recipe. ToList() once if you need the results twice.")
blank(S, "2.2", 2, "Take the first 5 items of an endless sequence.", "var firstFive = Forever().____(5);", ["Take"], "Take stops asking after n items, so an endless iterator is fine.")
tf(S, "2.2", 1, "A class with a public Add method that implements IEnumerable supports new Shelf { \"Tea\", \"Coffee\" }.", True, "Collection initializers call Add for each item.")

# ---------------- Section 3: ASP.NET Core MVC ----------------
S = 3
mc(S, "3.1", 1, "In MVC, which part handles the request and picks a view?", ["Model", "View", "Controller", "Middleware"], 2, "A controller action receives the request, works with models, and returns a result such as View().")
blank(S, "3.1", 1, "Restrict a route value to integers.", "[HttpGet(\"products/{id:____}\")]", ["int"], "Route constraints like {id:int} make /products/abc not match (404).")
mc(S, "3.1", 2, "What does RedirectToAction(\"Index\") return to the browser?", ["200 with the Index page", "302 with a Location header", "404", "500"], 1, "A redirect tells the browser to make a new GET request (Post/Redirect/Get).")
mc(S, "3.1", 2, "Which survives exactly one redirect?", ["ViewBag", "ViewData", "TempData", "A local variable"], 2, "TempData is stored (cookie by default) and read once on the next request.")
tf(S, "3.1", 2, "ViewBag and ViewData share the same storage.", True, "ViewBag.X is just a dynamic view over ViewData[\"X\"].")
blank(S, "3.1", 2, "Check validation in a POST action.", "if (!ModelState.____)\n{\n    return View(form);\n}", ["IsValid"], "ModelState.IsValid is false when binding or [Required]/[Range] checks failed.")
mc(S, "3.1", 2, "Why redirect after a successful POST?", ["Faster", "So refreshing the page doesn't re-submit the form", "Required by HTTP", "To clear cookies"], 1, "Post/Redirect/Get: a refresh repeats the GET, not the POST.")
mc(S, "3.1", 1, "Which attribute makes a property required in a form model?", ["[NotNull]", "[Required]", "[Mandatory]", "[Must]"], 1, "Data annotations like [Required], [Range], [StringLength] drive validation.")
mc(S, "3.1", 3, "RedirectToAction(\"Indx\") (typo) on a ProductsController gives...", ["Compile error", "500", "302 to /Products/Indx, then 404", "Redirects to Index anyway"], 2, "Action names are strings, checked only when the browser follows the redirect. nameof(Index) avoids this.")
blank(S, "3.1", 2, "Refer to the action name safely.", "return RedirectToAction(____(Index));", ["nameof"], "nameof(Index) is checked by the compiler; a typo won't compile.")
mc(S, "3.1", 2, "In a .cshtml file, what does @model ProductModel do?", ["Creates a ProductModel", "Declares the type of Model in the view", "Imports a namespace", "Binds a form"], 1, "Model is then strongly typed in the view.")
tf(S, "3.1", 2, "Razor encodes @product.Name, so <script> in a name is shown as text.", True, "@ output is HTML-encoded by default; Html.Raw turns that off (dangerous).")
mc(S, "3.2", 2, "A view component is best for...", ["A full page", "A reusable piece of UI with its own logic, like a sidebar", "An API endpoint", "Middleware"], 1, "Unlike a partial, a view component runs its own C# to fetch data.")
blank(S, "3.2", 2, "Render a view component in a view.", "@await Component.____(\"RecentActivitySidebar\")", ["InvokeAsync"], "Or as a tag helper: <vc:recent-activity-sidebar />.")
mc(S, "3.2", 3, "Where does View() inside a view component look for its view?", ["Views/Shared/Default.cshtml", "Views/Shared/Components/<Name>/Default.cshtml", "Components/<Name>.razor", "wwwroot"], 1, "The view component name without the ViewComponent suffix.")
mc(S, "3.2", 3, "A custom IModelBinder is for...", ["Logging", "Turning request text into a type the default binder can't parse (e.g. strict ISO dates)", "Validation only", "Routing"], 1, "3.2 binds dates only in yyyy-MM-dd format.")
tf(S, "3.2", 2, "A partial view can fetch its own data.", False, "A partial only renders the model it's given; a view component can run code.")
mc(S, "3.3", 1, "Which type receives an uploaded file in an action?", ["Stream", "IFormFile", "byte[] always", "HttpFile"], 1, "IFormFile gives the name, length, content type and a stream.")
mc(S, "3.3", 2, "Why not trust the uploaded file's name or extension?", ["They're always lowercase", "The client chooses them; check the real file signature (magic bytes)", "They're encrypted", "They're always empty"], 1, "A .jpg can be anything. 3.3 checks the first bytes and saves under a new random name.")
blank(S, "3.3", 2, "A form that uploads files needs this enctype.", "<form method=\"post\" enctype=\"____\">", ["multipart/form-data"], "Without it, the browser sends only the file name.")
mc(S, "3.3", 3, "With [RequestSizeLimit] exceeded, what did 3.3's avatar parameter become?", ["An empty file", "null", "The first part of the file", "An exception in the action"], 1, "So the action must null-check it; without the check it crashed with a 500.")
tf(S, "3.3", 2, "Saving uploads under Path.GetRandomFileName() avoids overwriting and path tricks like ../.", True, "Never build a path from the client's file name.")
mc(S, "3.1", 2, "Which HTTP method should a form that changes data use?", ["GET", "POST", "HEAD", "OPTIONS"], 1, "GET must be safe to repeat (links, refresh, crawlers).")
mc(S, "3.1", 3, "Model binding: an action Edit(int id, ProductForm form). Where can id come from?", ["Only the route", "Route values, the query string or form fields", "Only the body", "Only headers"], 1, "MVC looks in form fields, route values and the query string by default; [FromRoute] etc. pin one.")
